const PROGRESS = 'div[data-testid="playback-progressbar"] input[type="range"]';

function seek(deltaMs) {
  const input = morse.$$(PROGRESS)[0];
  if (!input) { morse.toast("Nothing is playing to seek"); return; }
  const min = Number(input.min) || 0;
  const max = Number(input.max);
  const cur = Number(input.value) || 0;
  if (!isFinite(max) || max <= 0) { morse.toast("Nothing is playing to seek"); return; }
  const next = Math.min(max, Math.max(min, cur + deltaMs));
  morse.type(input, next);
}

function makeButton(skipBtn, testid, label, text, deltaMs) {
  return morse.el("button", {
    class: skipBtn.className,
    type: "button",
    "data-testid": testid,
    "data-encore-id": "buttonTertiary",
    "aria-label": label,
    title: label,
    on: { click: () => seek(deltaMs) }
  }, morse.el("span", { class: "morse-seek-label", "aria-hidden": "true", text }));
}

morse.watch('button[data-testid="control-button-skip-back"]', (prev) => {
  const btn = makeButton(prev, "seek-back-15", "Rewind 15 seconds", "\u221215", -15000);
  prev.after(btn);
  return () => btn.remove();
});

morse.watch('button[data-testid="control-button-skip-forward"]', (next) => {
  const btn = makeButton(next, "seek-forward-15", "Forward 15 seconds", "+15", 15000);
  next.before(btn);
  return () => btn.remove();
});

